"""Independent reference calculation for the waveform fixtures (T096).

Reads only the raw ADC millivolts of each CSV and the nominal front-end
coefficients (frontend.json), the same inputs the firmware has, and computes the
values the firmware must reproduce:

- offset: per-channel mean over the window (integer number of cycles);
- V RMS and I RMS: sqrt(mean(x^2)) of the offset-corrected, scaled samples;
- active power: mean of v*i (FR-003), never Vrms*Irms, after aligning each current
  sample to its voltage instant by linear interpolation over the known
  one-conversion delay (half a pair period);
- energy: max(P, 0) * duration / 3600, in Wh;
- flags: `sample_gap` for missing pair indices, `adc_clipped` for rail values.

A flagged window is not valid, so its quantities are null. Results and
per-quantity tolerances go to expected.json (and the same numbers to expected.csv
for the C host tests):

    python tests/fixtures/waveforms/reference.py          # write expected.json
    python tests/fixtures/waveforms/reference.py --check  # verify it is current

It does not import generate.py; test_reference.py compares both against the
physical truth recorded in each CSV header.
"""

from __future__ import annotations

import argparse
import json
import math
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
FRONTEND: dict[str, Any] = json.loads((HERE / "frontend.json").read_text(encoding="utf-8"))
FIXTURES = ("sine_inphase", "lag60", "dc_offset", "clipping", "sample_gap", "no_current")

# Tolerances the firmware must meet against these values (relative and absolute;
# a value passes if it is within either). Bulb-on quantities are well above noise.
TOLERANCE: dict[str, dict[str, float]] = {
    "v_rms_v": {"rel": 0.005, "abs": 0.02},
    "i_rms_a": {"rel": 0.01, "abs": 0.01},
    "active_power_w": {"rel": 0.01, "abs": 0.05},
    "energy_wh": {"rel": 0.01, "abs": 0.0001},
}


@dataclass(frozen=True)
class Window:
    header: dict[str, Any]
    pair: list[int]
    v_mv: list[int]
    i_mv: list[int]


def load(name: str) -> Window:
    lines = (HERE / f"{name}.csv").read_text(encoding="utf-8").splitlines()
    header = json.loads(lines[0].removeprefix("# "))
    if lines[1] != "pair,v_mv,i_mv":
        raise ValueError(f"{name}: unexpected columns {lines[1]!r}")
    rows = [tuple(int(x) for x in line.split(",")) for line in lines[2:]]
    return Window(header, [r[0] for r in rows], [r[1] for r in rows], [r[2] for r in rows])


def gains() -> tuple[float, float]:
    v, c = FRONTEND["voltage"], FRONTEND["current"]
    gv = 1000.0 * v["r2_ohm"] / (v["r1_ohm"] + v["r2_ohm"])  # mV per V
    gi = c["sensitivity_mv_per_a"] * c["r4_ohm"] / (c["r3_ohm"] + c["r4_ohm"])  # mV per A
    return gv, gi


def flags_of(w: Window) -> list[str]:
    flags = []
    if any(b - a != 1 for a, b in zip(w.pair, w.pair[1:], strict=False)) or w.pair[0] != 0:
        flags.append("sample_gap")
    rails = (FRONTEND["adc_min_mv"], FRONTEND["adc_max_mv"])
    if any(x in rails for x in w.v_mv) or any(x in rails for x in w.i_mv):
        flags.append("adc_clipped")
    return sorted(flags)


def _rms(xs: list[float]) -> float:
    return math.sqrt(sum(x * x for x in xs) / len(xs))


def compute(w: Window, phase_correction: bool = True) -> dict[str, Any]:
    gv, gi = gains()
    mean_v = sum(w.v_mv) / len(w.v_mv)
    mean_i = sum(w.i_mv) / len(w.i_mv)
    v = [(x - mean_v) / gv for x in w.v_mv]
    i = [(x - mean_i) / gi for x in w.i_mv]
    delay = FRONTEND["current_delay_conversions"] / 2  # in pair periods: 0.5
    products = []
    for k in range(len(w.pair)):
        if not phase_correction:
            products.append(v[k] * i[k])
        elif k > 0 and w.pair[k] - w.pair[k - 1] == 1:
            # i[k] was taken `delay` pairs after v[k]; interpolate back to v's instant.
            i_at_v = i[k] - delay * (i[k] - i[k - 1])
            products.append(v[k] * i_at_v)
    power = sum(products) / len(products)
    duration = float(w.header["duration_s"])
    return {
        "v_rms_v": _rms(v),
        "i_rms_a": _rms(i),
        "active_power_w": power,
        "energy_wh": max(power, 0.0) * duration / 3600.0,
    }


def expected() -> dict[str, Any]:
    out: dict[str, Any] = {
        "_comment": "Generated by reference.py from the CSVs and frontend.json; do not edit.",
        "frontend": FRONTEND,
        "tolerance": TOLERANCE,
        "fixtures": {},
    }
    for name in FIXTURES:
        w = load(name)
        flags = flags_of(w)
        values = compute(w)
        below_noise = values["i_rms_a"] < FRONTEND["zero_noise_current_a"]
        entry: dict[str, Any] = {
            "description": w.header["description"],
            "pairs": len(w.pair),
            "duration_s": w.header["duration_s"],
            "flags": flags,
            "valid": not flags,
            "current_below_noise": below_noise,
        }
        for key, value in values.items():
            entry[key] = None if flags else round(value, 6)
        out["fixtures"][name] = entry
    return out


QUANTITIES = ("v_rms_v", "i_rms_a", "active_power_w", "energy_wh")


def render() -> str:
    return json.dumps(expected(), indent=2, sort_keys=True) + "\n"


def render_csv() -> str:
    """The same values flattened for the C host tests (expected.json stays canonical)."""
    exp = expected()
    rows = ["fixture,valid,flags," + ",".join(QUANTITIES)]
    for name, e in exp["fixtures"].items():
        vals = ["" if e[q] is None else repr(e[q]) for q in QUANTITIES]
        rows.append(f"{name},{int(e['valid'])},{'|'.join(e['flags'])}," + ",".join(vals))
    for kind in ("rel", "abs"):
        vals = [repr(exp["tolerance"][q][kind]) for q in QUANTITIES]
        rows.append(f"tolerance_{kind},,," + ",".join(vals))
    return "\n".join(rows) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--check", action="store_true", help="fail if expected.json is stale")
    args = parser.parse_args(argv)
    outputs = {HERE / "expected.json": render(), HERE / "expected.csv": render_csv()}
    for path, text in outputs.items():
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != text:
                print(f"{path.name} is out of date; run reference.py", file=sys.stderr)
                return 1
        else:
            path.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
